const rooms=[
 {name:'STARTPORTEN',desc:'Startporten. Varmt fakkellys viser veien inn i hulen. Her begynner eventyret.',enc:'INGEN MØTE',encText:'Her kan barnet bli kjent med kartet og helten.',icon:'🔥',art:'🔥',signals:['VARMT FAKKELLYS','TRYGG INNGANG'],mood:'ROLIG',visited:true,reachable:false,locked:false,combat:false},
 {name:'FOSSEHALLEN',desc:'Fossehallen. Vann bruser gjennom en høy sprekk, og en smal bro glitrer av dråper.',enc:'SPOR I VANNET',encText:'Noe blankt ligger mellom steinene ved vannkanten.',icon:'💧',art:'💧',signals:['BRUSENDE VANN','BLANKT GLIMT'],mood:'NYSGJERRIG',visited:true,reachable:true,locked:false,combat:false},
 {name:'MÅNESTEINHALLEN',desc:'Månesteinhallen. Et mykt, blått lys fyller den store hulen. Runer gløder svakt i veggene, og en krystall kaster lys over vannet på gulvet.',enc:'STEINVENN',encText:'En liten steinvenn kikker nysgjerrig på deg. Den virker vennlig. Kanskje den vil vise deg noe?',icon:'🪨',art:'💎',signals:['MYKT BLÅTT LYS','RUNER I VEGGEN','LYD AV VANN'],mood:'VENNLIG',visited:true,reachable:true,locked:false,combat:false},
 {name:'SOPPSALEN',desc:'Soppsalen. Store sopper lyser varmt mellom steinene, og små sporer svever i luften.',enc:'SOPPPRINSEN',encText:'En liten venn dukker fram bak den største soppen.',icon:'🍄',art:'🍄',signals:['LYSENDE SOPPER','SVEVENDE SPORER'],mood:'VENNLIG',visited:false,reachable:true,locked:false,combat:false},
 {name:'BROEN',desc:'Broen. En gammel trebro går over en mørk sprekk. Tauverket knirker, men veien er synlig.',enc:'UTFORDRING',encText:'Broen ser gammel ut. Barnet bestemmer hvordan helten vil nærme seg problemet.',icon:'🌉',art:'🌉',signals:['KNIRKENDE TAU','MØRK SPREKK'],mood:'USIKKER',visited:false,reachable:true,locked:false,combat:false},
 {name:'VOKTERENS ROM',desc:'Vokterens rom. En tung figur står mellom helten og veien videre.',enc:'VOKTER',encText:'Vokteren angriper ikke først. Den ser ut til å passe på noe.',icon:'🗿',art:'🗿',signals:['STILLE VOKTER','VEIEN VIDERE'],mood:'AVVENTENDE',visited:false,reachable:false,locked:true,combat:true},
 {name:'UNDERJORDSSJØEN',desc:'Underjordssjøen. Turkist vann fyller hulen. En liten brygge forsvinner inn i mørket.',enc:'VENN VED VANNET',encText:'Noe beveger seg rolig ute ved vannkanten.',icon:'🌊',art:'🌊',signals:['TURKIST VANN','LITEN BRYGGE'],mood:'ROLIG',visited:false,reachable:false,locked:false,combat:false},
 {name:'GRUVEGANGEN',desc:'Gruvegangen. Gamle skinner og trestøtter går videre mellom krystallårer i fjellet.',enc:'SKJULT LYD',encText:'Et svakt pling kommer fra et sted under steinene.',icon:'⛏️',art:'⛏️',signals:['GAMLE SKINNER','SVAKT PLING'],mood:'MYSTISK',visited:false,reachable:false,locked:false,combat:false},
 {name:'UKJENT',desc:'Dette rommet er ikke avslørt ennå.',enc:'IKKE AVSLØRT',encText:'Kartet viser ikke hva som finnes her før eventyret faktisk avslører det.',icon:'?',art:'?',signals:['IKKE AVSLØRT'],mood:'UKJENT',visited:false,reachable:false,locked:false,combat:false,unknown:true}
];
let current=2,selected=2;
const $=id=>document.getElementById(id);
function updatePanel(i){selected=i;const r=rooms[i];document.querySelectorAll('.node').forEach(n=>n.classList.toggle('selected',Number(n.dataset.room)===i));$('roomTitle').textContent=r.name;$('roomText').textContent=r.desc;$('portrait').textContent=r.icon;$('roomArt').dataset.symbol=r.art;$('artCaption').textContent=r.unknown?'IKKE AVSLØRT':r.signals.join(' · ');$('encounterTitle').textContent=r.enc;$('encounterText').textContent=r.encText;$('mood').textContent=r.mood;$('signals').innerHTML=r.signals.map(s=>`<span class="signal">${s}</span>`).join('');const here=i===current;$('roomKicker').textContent=here?'DU ER HER':'VALGT PÅ KARTET';$('peekBadge').hidden=here;$('visitBadge').textContent=r.unknown?'UKJENT':r.visited?'BESØKT':r.locked?'LÅST':'KJENT';$('dmContext').textContent=`Aktuelt: ${r.name} · ${r.enc}`;$('authoredText').textContent=r.unknown?'Ingen romdetaljer er avslørt for spilleren ennå. Forteller må ikke lekke skjult innhold.':`${r.name}, signalene som vises og ${r.enc} er det skrevne innholdet i denne visningen.`;$('resolvedText').textContent=r.locked?'Denne forbindelsen kan ikke passeres før den faktiske låsen/gaten er løst i kanonisk state.':r.enc==='VOKTER'?'Vokteren kan løses med en plausibel ikke-voldelig løsning, eller kamp hvis barnet velger det og Storylet tillater det.':'Barnet kan undersøke, snakke, gå videre eller prøve en annen plausibel handling når fiksjonen tillater det.';$('combatBtn').classList.toggle('hidden',!r.combat);const canGo=!here&&!r.unknown&&!r.locked&&r.reachable;$('goBtn').disabled=!canGo;$('goBtn').textContent=here?'DU ER HER':r.unknown?'IKKE AVSLØRT':r.locked?'LÅST':canGo?'GÅ HIT':'IKKE TILGJENGELIG';$('navTitle').textContent=here?'DU ER I DETTE ROMMET':canGo?'ROMMET ER TILGJENGELIG':r.locked?'FORBINDELSEN ER LÅST':r.unknown?'ROMMET ER SKJULT':'IKKE TILGJENGELIG HERFRA';$('navText').textContent=here?'Velg et annet kjent rom på kartet for å se på det uten å flytte helten.':canGo?'Å se på rommet flyttet ikke helten. Velg GÅ HIT som egen handling hvis dere faktisk vil gå dit.':r.locked?'Kartet kan vise rommet, men ikke passere låsen uten en faktisk løsning.':r.unknown?'Ingen illustrasjon eller tekst skal lekke hva som finnes her ennå.':'Det finnes ingen åpen forbindelse fra helten til dette rommet akkurat nå.';}
function goSelected(){const r=rooms[selected];if(selected===current||!r.reachable||r.locked||r.unknown)return;current=selected;document.querySelectorAll('.node').forEach(n=>{const i=Number(n.dataset.room);n.classList.toggle('current',i===current);if(i===current){n.classList.add('visited');rooms[i].visited=true}});updatePanel(current);}
document.querySelectorAll('.node').forEach(n=>n.addEventListener('click',()=>updatePanel(Number(n.dataset.room))));$('goBtn').addEventListener('click',goSelected);
function openOverlay(id){$(id).classList.remove('hidden')}function closeOverlay(id){$(id).classList.add('hidden')}
['dmBtn','dmTop','dmMobile'].forEach(id=>$(id)&&$(id).addEventListener('click',()=>openOverlay('dm')));$('dmClose').addEventListener('click',()=>closeOverlay('dm'));$('dm').addEventListener('click',e=>{if(e.target===$('dm'))closeOverlay('dm')});$('bagBtn').addEventListener('click',()=>openOverlay('bag'));$('bagClose').addEventListener('click',()=>closeOverlay('bag'));$('bag').addEventListener('click',e=>{if(e.target===$('bag'))closeOverlay('bag')});
$('lookBtn').addEventListener('click',()=>{const b=$('lookBtn');b.textContent='✓ SER DEG RUNDT';setTimeout(()=>b.innerHTML='👁️<br>SE DEG RUNDT',850)});$('continueBtn').addEventListener('click',()=>{document.querySelector('.map-card').scrollIntoView({behavior:'smooth',block:'start'})});
document.querySelectorAll('.mobile-tabs button[data-surface]').forEach(b=>b.addEventListener('click',()=>{const s=b.dataset.surface;document.querySelectorAll('.mobile-tabs button[data-surface]').forEach(x=>x.classList.toggle('active',x===b));['mapSurface','roomSurface','bagSurface'].forEach(id=>$(id).classList.add('mobile-surface-hidden'));$({map:'mapSurface',room:'roomSurface',bag:'bagSurface'}[s]).classList.remove('mobile-surface-hidden')}));
updatePanel(2);
